#include <iostream>
#include <string>
using namespace std;

const int MAXM = 1005;
int data[MAXM];
int front = 0, rear = 0, m;

int main() {
    int q;
    if (!(cin >> m >> q)) return 0;

    while (q--) {
        string op;
        cin >> op;
        if (op == "enqueue") {
            long long x; cin >> x;
            if ((rear + 1) % m != front) {     // 不满才入队
                rear = (rear + 1) % m;         // 先移指针
                data[rear] = (int)x;           // 再放元素
            }
        } else if (op == "dequeue") {
            if (front == rear) { cout << "error\n"; continue; }
            front = (front + 1) % m;           // 先移指针
            cout << data[front] << "\n";      // 再取元素
        } else if (op == "front") {
            if (front == rear) { cout << "error\n"; continue; }
            cout << data[(front + 1) % m] << "\n";
        } else if (op == "size") {
            cout << (rear - front + m) % m << "\n";
        }
    }
    return 0;
}
